import re

def get_blocks(text):
    blocks = re.split(r'\n?\s*\[(.*?)\]\s*\n', text)
    if blocks[0].strip() == '':
        blocks = blocks[1:]
    res = {}
    for i in range(0, len(blocks), 2):
        res[blocks[i]] = blocks[i+1].strip()
    return res

with open('/app/script.txt', 'r') as f:
    text = f.read()

blocks = get_blocks(text)
defined_nodes = set(blocks.keys())
all_targets = set()

for node_id, content in blocks.items():
    lines = [l.strip() for l in content.split('\n') if l.strip()]
    for line in lines:
        if '->' in line:
            target = line.split('->')[-1].strip()
            all_targets.add(target)

print("Defined nodes:", len(defined_nodes))
print("Targets:", len(all_targets))
print("Targets not defined:", all_targets - defined_nodes)

