import re

def get_blocks(text):
    blocks = re.split(r'\n?\s*\[(.*?)\]\s*\n', text)
    if blocks[0].strip() == '':
        blocks = blocks[1:]
    res = []
    for i in range(0, len(blocks), 2):
        res.append((blocks[i], blocks[i+1].strip()))
    return res

with open('/app/script.txt', 'r') as f:
    text = f.read()

blocks = get_blocks(text)
adj = {}
first_node = blocks[0][0]

for node_id, content in blocks:
    lines = [l.strip() for l in content.split('\n') if l.strip()]
    adj[node_id] = []
    for line in lines:
        if '->' in line:
            target = line.split('->')[-1].strip()
            adj[node_id].append(target)

visited = set()
stack = [first_node]
while stack:
    node = stack.pop()
    if node not in visited:
        visited.add(node)
        if node in adj:
            for neighbor in adj[node]:
                stack.append(neighbor)

defined_nodes = set(n[0] for n in blocks)
unreachable = defined_nodes - visited
print("Unreachable nodes:", unreachable)

