import json
import re
import sys

def parse_script(text: str):
    nodes = []
    edges = []

    # Split text into blocks based on [NodeName]
    # We use a lookahead for the next [ or end of string
    blocks = re.findall(r'\[(.*?)\]\s*(.*?)(?=\s*\[|$)', text, re.DOTALL)

    node_ids = []
    for node_id, content in blocks:
        node_id = node_id.strip()
        content = content.strip()
        lines = [l.strip() for l in content.split('\n') if l.strip()]

        if not lines:
            # Empty node?
            nodes.append({
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "line"
            })
            continue

        # Check if it contains choices (starting with digit.)
        is_choice = any(re.match(r'^\d+\.', l) for l in lines)

        if is_choice:
            prompt_text = ""
            prompt_speaker = ""
            # Look for a dialogue line before choices
            for l in lines:
                if re.match(r'^\d+\.', l):
                    break
                match = re.match(r'^(.*?):\s*(.*?)(?:\s*->\s*(.*?))?$', l)
                if match:
                    prompt_speaker = match.group(1)
                    prompt_text = match.group(2)
                    # Note: if there's an arrow in the prompt line of a choice node, 
                    # it might be an edge too, but typically it's just text.
                    # In this script, choice nodes don't have prompt lines.

            nodes.append({
                "id": node_id,
                "text": prompt_text,
                "speaker": prompt_speaker,
                "type": "choice"
            })

            for l in lines:
                choice_match = re.match(r'^\d+\.\s*(.*?)\s*->\s*(.*?)$', l)
                if choice_match:
                    edges.append({
                        "from": node_id,
                        "to": choice_match.group(2).strip(),
                        "text": choice_match.group(1).strip()
                    })
        else:
            # Line node
            # Take the first line
            line = lines[0]
            match = re.match(r'^(.*?):\s*(.*?)\s*->\s*(.*?)$', line)
            if match:
                speaker = match.group(1).strip()
                text_content = match.group(2).strip()
                target = match.group(3).strip()

                nodes.append({
                    "id": node_id,
                    "text": text_content,
                    "speaker": speaker,
                    "type": "line"
                })
                edges.append({
                    "from": node_id,
                    "to": target,
                    "text": ""
                })
            else:
                # Line without arrow
                match_no_arrow = re.match(r'^(.*?):\s*(.*?)$', line)
                if match_no_arrow:
                    nodes.append({
                        "id": node_id,
                        "text": match_no_arrow.group(2).strip(),
                        "speaker": match_no_arrow.group(1).strip(),
                        "type": "line"
                    })
                else:
                    # Narrator text or something else
                    nodes.append({
                        "id": node_id,
                        "text": line,
                        "speaker": "",
                        "type": "line"
                    })

    # Add missing nodes (like 'End')
    defined_ids = set(n['id'] for n in nodes)
    targets = set(e['to'] for e in edges)
    for t in targets:
        if t not in defined_ids:
            nodes.append({
                "id": t,
                "text": t,
                "speaker": "",
                "type": "line"
            })
            defined_ids.add(t)

    return {"nodes": nodes, "edges": edges}

def generate_dot(graph):
    dot = ["digraph dialogue {"]
    dot.append("    rankdir=LR;")
    dot.append("    node [fontname=\"Arial\"];")

    for node in graph['nodes']:
        id_val = node['id']
        speaker = node['speaker']
        text = node['text']
        node_type = node['type']

        if node_type == 'choice':
            shape = "diamond"
            color = "lightblue"
        else:
            shape = "box"
            color = "white"

        label_parts = []
        if speaker:
            label_parts.append(f"<b>{speaker}</b>")
        if text:
            label_parts.append(text)

        if not label_parts:
            label = id_val
        else:
            label = "<br/>".join(label_parts)
            label = f"<i>{id_val}</i><br/>{label}"

        # DOT HTML-like labels
        dot.append(f'    "{id_val}" [shape={shape}, style=filled, fillcolor={color}, label=<{label}>];')

    for edge in graph['edges']:
        from_node = edge['from']
        to_node = edge['to']
        text = edge['text']

        dot.append(f'    "{from_node}" -> "{to_node}" [label="{text}"];')

    dot.append("}")
    return "\n".join(dot)

if __name__ == "__main__":
    try:
        with open('/app/script.txt', 'r') as f:
            script_text = f.read()
    except FileNotFoundError:
        print("script.txt not found")
        sys.exit(1)

    graph = parse_script(script_text)

    with open('/app/dialogue.json', 'w') as f:
        json.dump(graph, f, indent=2)

    dot_content = generate_dot(graph)
    with open('/app/dialogue.dot', 'w') as f:
        f.write(dot_content)

